INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1183895, 144801, 22734, '<td valign="top">A very nice effect approaching the Dance of Shiva. The sepia works great and the double exposures do not detract from the general feel serenity. The creative execution exceeds the challenge by adding an extra ingredient to the character study. Bumping up.</td>', 'A very nice effect approaching the Dance of Shiva. The sepia works great and the double exposures do not detract from the general feel serenity. The creative execution exceeds the challenge by adding an extra ingredient to the character study. Bumping up.', '2005-02-20 15:09:11.000000', NULL, 1),
